      attribute :distribution, :string
      attribute :interval_kind, :string
      attribute :lower, :string
      attribute :magnitude, :string
      attribute :plus_minus, :string
      attribute :relative_magnitude, :string
      attribute :shared_exponent, :string
      attribute :uncertainty_class, :string
